// Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

const VERIFY = 'scripts/verify.sh';
const NORMALIZER = 'scraper/normalize.py';
const SELFTEST = '--selftest';

// Scoped parse rather than a grep: verify.sh labels the step
// `step "Normalizer self-test — normalize.py --selftest"`, so a plain grep for
// the two tokens passes even after the real invocation is deleted — the label
// alone would satisfy it. Drop comment lines and the quoted argument of every
// `step` call, then look for a surviving command line.
function commandLines(sh) {
  return sh
    .split('\n')
    .filter((l) => !/^\s*#/.test(l))
    .map((l) => l.replace(/\bstep\s+(["'])(?:(?!\1).)*\1/g, ''))
    // A trailing comment can carry the tokens too (`node --check  # not normalize.py --selftest`).
    .map((l) => l.replace(/\s#.*$/, ''));
}

const rule = {
  id: 'edfringe-normalizer-selftest-in-verify',
  severity: 'blocking',
  description: "scripts/verify.sh runs the normalizer's offline self-test (python3 scraper/normalize.py --selftest)",
  why:
    "the live edfringe API is unreachable from a session, so the normalizer self-test is the ONE transform check that runs offline — drop it from the gate and every scraper change ships with no verification at all, in a repo where nothing else can stand in for it",
  doc: 'RULES.md',

  run(ctx) {
    // Relevance-first: no normalizer, or one with no self-test to run, is not
    // this rule's business.
    if (!ctx.files.includes(NORMALIZER)) return [];
    const normalizer = ctx.read(NORMALIZER);
    if (normalizer === null || !normalizer.includes(SELFTEST)) return [];

    const sh = ctx.files.includes(VERIFY) ? ctx.read(VERIFY) : null;
    if (sh === null) return []; // relevance-first: no verification gate in this tree

    const wired = commandLines(sh).some((l) => l.includes('normalize.py') && l.includes(SELFTEST));
    if (wired) return [];

    return [{
      rule: rule.id,
      severity: rule.severity,
      file: VERIFY,
      line: null,
      what: `${NORMALIZER} supports ${SELFTEST} but ${VERIFY} never invokes it (a step label naming it does not count — only a command line does)`,
      why: rule.why,
      fix: `restore the step to ${VERIFY}: \`python3 ${NORMALIZER} ${SELFTEST}\` — both the pre-commit hook and CI run that script, so this is the only place wiring it makes it a gate`,
      doc: rule.doc,
    }];
  },
};

export default rule;

// Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

// Everything the browser fetches out of `data/` is written by
// `scraper/normalize.py` — its module header is the authoritative list:
//
//   data/normalized/shows.json, shows.min.json, descriptions.min.json
//   data/venues.json
//   data/days/<YYYY-MM-DD>.json + data/days/index.json
//
// So a file under `data/` that isn't one of those shapes came from a hand, a
// throwaway probe, or a force-added raw cache — and the next `refresh-shows`
// run neither maintains it nor knows about it. The patterns are deliberately
// shape-based (a dir plus a `.json` leaf) rather than a literal file list, so a
// new day file or a new normalized artefact doesn't trip the check; a whole new
// output *directory* does, which is the moment a human should confirm the
// producer really writes it.
const ALLOWED_PATTERNS = [
  /^data\/normalized\/[^/]+\.json$/,
  /^data\/days\/[^/]+\.json$/,
];

// Grandfathered: the pre-pipeline mock dataset the design-concepts prototypes
// still load, documented as such in README.md. It is not normalizer output and
// never will be; it is exempt by name so the rule can stay strict for everything
// else. Do not add to this list — new data comes from the normalizer.
const ALLOWED_FILES = new Set(['data/venues.json', 'data/shows.json']);

// The one committed file under data/ that is an *input* to normalize.py rather
// than an output of it: the fetch-once ticket-price cache written by
// scraper/fetch_prices.py. It satisfies what this rule is actually protecting —
// a script in this repo produces it, and nothing silently destroys it (the
// normalizer only ever reads it) — so it is named here rather than exempted by
// shape. Anything else claiming to be a second input needs the same scrutiny
// this entry got, which is why it is one name and not a pattern.
const ALLOWED_INPUTS = new Map([
  ['data/prices.json', 'scraper/fetch_prices.py'],
]);

// The bulky raw scrape cache is git-ignored (`.gitignore`) precisely because it
// is regenerable by `scraper/fetch_shows.py`. It reaches the tree only via a
// deliberate `git add -f`, so it gets its own finding: the fix is to un-stage
// it, not to delete data the site needs.
const RAW_CACHE = 'data/raw_pages/';

const rule = {
  id: 'edfringe-data-dir-is-generator-output',
  severity: 'blocking',
  description: "Every committed file under data/ is one of scraper/normalize.py's outputs — no hand-made files, no probe dumps, no raw cache",
  why:
    'data/ is generator output that the browser fetches and the next refresh-shows run rewrites wholesale, so a file that the normalizer does not produce is either silently served to users or silently destroyed — and either way the thing that produced it is not in the repo',
  doc: 'RULES.md',

  run(ctx) {
    const out = [];
    for (const f of ctx.files.filter((p) => p.startsWith('data/')).sort()) {
      if (f.startsWith(RAW_CACHE)) {
        out.push(finding(f,
          `${f} is the git-ignored raw scrape cache — un-track it (\`git rm --cached ${f}\`); scraper/fetch_shows.py regenerates it, so it is never committed`,
        ));
        continue;
      }
      if (ALLOWED_FILES.has(f) || ALLOWED_INPUTS.has(f)) continue;
      if (ALLOWED_PATTERNS.some((re) => re.test(f))) continue;
      out.push(finding(f,
        `delete ${f} — everything under data/ is scraper/normalize.py's output (data/venues.json, data/normalized/*.json, data/days/*.json), plus the named scraper inputs (${[...ALLOWED_INPUTS.keys()].join(', ')}). A probe informs the normalizer, it does not feed it: fix scraper/normalize.py and re-run it instead. If normalize.py genuinely writes ${f} now, add its shape to this check's allowlist in the same commit; if another scraper produces it as an input, add it to ALLOWED_INPUTS naming that script`,
      ));
    }
    return out;
  },
};

function finding(file, fix) {
  return {
    rule: rule.id,
    severity: rule.severity,
    file,
    line: null,
    what: `${file} is under data/ but is not something scraper/normalize.py produces`,
    why: rule.why,
    fix,
    doc: rule.doc,
  };
}

export default rule;

